const body = $json.body;
const entry = body.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];

// Si no hay mensaje de texto (puede ser una actualización de estado u otro evento), paramos aquí.
if (!message || message.type !== 'text') {
  return [];
}

// Meta manda el nombre del perfil de WhatsApp junto al mensaje. Puede no
// venir (perfil sin nombre, o ajustes de privacidad), asi que es opcional.
// Se busca por wa_id en vez de coger el primero: en un webhook agrupado
// podria haber varios contactos y el primero no tiene por que ser el nuestro.
const contacto =
  value?.contacts?.find((c) => c.wa_id === message.from) || value?.contacts?.[0];
const nombre = contacto?.profile?.name?.trim() || null;

return [{
  json: {
    phone_number_id: value.metadata.phone_number_id,
    from: message.from,
    message_text: message.text.body,
    contact_name: nombre,
  }
}];

