parameters.jsCode:
// Este nodo recibe un item por cada módulo activo del cliente y los reduce a
// uno solo: a partir de aquí el flujo vuelve a tratar un único mensaje.
const modulos = $input.all().map((i) => i.json.module).filter(Boolean);

// Un bot de tienda no debe hablar de citas. En vez de duplicar el workflow por
// cliente, se mira si tiene activo el módulo de agenda y se adapta el contexto.
// Así el mismo workflow sirve para una clínica que reserva y para una tienda
// que solo asesora.
const tiene_agenda = modulos.includes('calendar');

const pregunta = String($('Extraer mensaje').first().json.message_text || '');

// Palabras demasiado comunes para buscar un producto con ellas: "cuanto",
// "precio" o "teneis" aparecen en media tienda y solo añaden ruido.
const VACIAS = new Set([
  'cuanto', 'cuanta', 'cuantos', 'cuantas', 'cuesta', 'cuestan', 'precio',
  'precios', 'vale', 'valen', 'tiene', 'tienen', 'teneis', 'hola', 'buenas',
  'gracias', 'quiero', 'queria', 'necesito', 'busco', 'buscaba', 'sobre',
  'para', 'como', 'donde', 'porque', 'puedo', 'puede', 'pueden', 'hacer',
  'decir', 'saber', 'favor', 'euros', 'envio', 'envios', 'pedido', 'tienda',
  'producto', 'productos', 'algun', 'alguna', 'tambien', 'mucho', 'mucha',
  'sois', 'estais', 'venden', 'vendeis', 'comprar', 'pagar', 'esta', 'este',
  'unas', 'unos', 'otra', 'otro', 'cual', 'cuales', 'vuestro', 'vuestra',
]);

// El catálogo guarda los nombres en singular ("Cesto jacinto Valle") pero la
// gente pregunta en plural ("¿tenéis cestos?"). Sin esto, "cestos" no encuentra
// ni un producto y "cesto" encuentra tres. Como la comparación lleva comodines
// a los dos lados, acortar la palabra solo puede encontrar de más, nunca de
// menos; el mínimo de cuatro letras evita raíces tan cortas que valgan para
// cualquier cosa.
const singular = (p) => {
  const raiz = p.replace(/(es|s)$/, '');
  return raiz.length >= 4 ? raiz : p;
};

// Se comparan sin tildes porque por WhatsApp casi nadie las escribe, y la
// función buscar_productos aplica unaccent por el otro lado.
const terminos = [...new Set(
  pregunta
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    // Se descartan las palabras vacías dos veces, antes y después de recortar
    // el plural: si no, "teneis" pasaría el filtro convertido en "tenei" y se
    // buscaría en el catálogo un producto que contenga esa sílaba.
    .filter((p) => p.length >= 4 && !VACIAS.has(p))
    .map(singular)
    .filter((p) => !VACIAS.has(p))
)].slice(0, 5);

return [{
  json: {
    tiene_agenda,
    modulos,
    pregunta,
    terminos,
    // Sin términos útiles no tiene sentido mirar el catálogo: se piden cero
    // filas en lugar de lanzar una consulta que devolvería cualquier cosa.
    limite_productos: terminos.length ? 6 : 0,
  },
}];

// El nodo anterior devuelve una fila por item; aquí se recogen todas en un
// único item para que el resto del flujo siga tratando un solo mensaje.
//
// «Always Output Data» está activado en la búsqueda: cuando no hay resultados
// llega un item vacío en lugar de ninguno. Sin eso, un cliente sin conocimiento
// cargado cortaría el flujo aquí y el bot no contestaría nada.
const fragmentos = $input
  .all()
  .map((i) => i.json)
  .filter((f) => f && f.content);

return [{ json: { fragmentos } }];

